    public TrainingMetrics? LastTrainingMetrics { get; private set; }
    public string[] CategoryLabels { get; private set; } = [];

    public TicketModelService(ILogger<TicketModelService> logger, IWebHostEnvironment env)
    {
        _mlContext = new MLContext(seed: 42);
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "ticket_model.zip");
        _logger = logger;
    }

    public void TrainAndSave()
    {
        var data = _mlContext.Data.LoadFromTextFile<TicketInput>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // With a small dataset, use the full set for training and evaluate on it.
        // In production, use TrainTestSplit with a larger dataset.
        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _logger.LogInformation("Training ticket classifier model...");
        var model = pipeline.Fit(split.TrainSet);

        // Extract label order from the trained model's key-value mapping
        var transformedData = model.Transform(split.TrainSet);
        var labelColumn = transformedData.Schema["Label"];
        var keyType = labelColumn.Type as KeyDataViewType;
        if (keyType is not null)
        {
            VBuffer<ReadOnlyMemory<char>> labels = default;
            transformedData.Schema["Label"].GetKeyValues(ref labels);
            CategoryLabels = labels.DenseValues().Select(v => v.ToString()).ToArray();
        }

        var predictions = model.Transform(split.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, "Label");

        LastTrainingMetrics = new TrainingMetrics
        {
            MicroAccuracy = metrics.MicroAccuracy,
            MacroAccuracy = metrics.MacroAccuracy,
            LogLoss = double.IsFinite(metrics.LogLoss) ? metrics.LogLoss : -1,
            LogLossReduction = double.IsFinite(metrics.LogLossReduction) ? metrics.LogLossReduction : -1
        };

        _logger.LogInformation(
            "Model trained — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}, LogLossReduction: {Reduction:F4}",
            metrics.MicroAccuracy, metrics.MacroAccuracy, metrics.LogLoss, metrics.LogLossReduction);

        _mlContext.Model.Save(model, split.TrainSet.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);
    }

